const interval = $('Reporting Interval').first().json;
function section(name) {
  const response = $(name).first().json;
  const status = response.statusCode || response.body?.error?.code;
  if (response.error || status >= 400 || response.body?.error) {
    const message = String(response.error?.message || response.error || '');
    const kind = status === 401 || /oauth|credential|authentication|unauthorized/i.test(message) ? 'OAuth/autenticazione' : status === 403 ? 'accesso negato' : status === 429 ? 'rate-limit' : status ? 'errore API' : 'errore di trasporto';
    return {rows: [], error: `${kind} — HTTP ${status || 'non disponibile'}; sezione indisponibile; nessun retry automatico.`};
  }
  return {rows: Array.isArray(response.body?.rows) ? response.body.rows : []};
}
const dateSection = section('Query Dates');
const dates = dateSection.rows;
const present = new Set(dates.map(row => row.keys[0]));
const missing = [];
for (let day = 0; day < 7; day++) {
  const date = new Date(interval.startDate + 'T12:00:00Z');
  date.setUTCDate(date.getUTCDate() + day);
  const key = date.toISOString().slice(0, 10);
  if (!present.has(key)) missing.push(key);
}
const text = [
  '*Baialupo — report SEO settimanale*',
  'Property: sc-domain:baialupo.com • ricerca web',
  `Intervallo inclusivo: ${interval.startDate} → ${interval.endDate} (America/Los_Angeles)`,
  'Maturità richiesta: dataState=final; fine intervallo tre giorni di calendario Pacific prima di oggi. L’offset non garantisce la presenza di tutte le date.',
  `Copertura restituita: ${present.size}/7 giorni. Date assenti: ${missing.join(', ') || 'nessuna'}.`,
];
if (dateSection.error) text.push(`Date: ${dateSection.error}`);
const clicks = dates.reduce((sum, row) => sum + row.clicks, 0);
const impressions = dates.reduce((sum, row) => sum + row.impressions, 0);
if (!dates.length || !(impressions > 0)) {
  text.push('Totali: nessun dato utile; assenza di metriche non equivale a zero traffico accertato.');
} else {
  const ctr = (clicks / impressions * 100).toFixed(2) + '%';
  const position = (dates.reduce((sum, row) => sum + row.position * row.impressions, 0) / impressions).toFixed(2);
  text.push(`Totali delle sole date restituite — Clic: ${clicks} • Impressioni: ${impressions} • CTR: ${ctr} • Posizione: ${position} (pesata per impressioni).`);
}
for (const [name, label] of [['Query Pages', 'Pagine'], ['Query Queries', 'Query']]) {
  const result = section(name);
  text.push(`*${label} principali — campione API (limite 10 righe, nessuna paginazione)*`);
  if (result.error) text.push(`${label}: ${result.error}`);
  else if (!result.rows.length) text.push(`${label}: nessun dato utile.`);
  for (const row of result.rows) text.push(`${row.keys[0]} — clic ${row.clicks}, impressioni ${row.impressions}`);
}
text.push('L’API restituisce le righe principali, non tutte; i campioni pagina/query non ricostruiscono i totali. Nessun confronto storico o attribuzione SEO.');
return [{json: {text: text.join('\n')}}];
